/****************************************************************************
 * app/home_scense/ac_ir_control.h
 * 空调红外(CIR)发射/学习封装 —— 走 NuttX LIRC 设备 /dev/lirc0。
 *
 * 硬件: 全志 R528 专用 CIR TX(GPIO_PB0 复用) → S9013 → 红外发射管;
 *       IRM-3638T 38kHz 接收头 → CIR RX。板级 defconfig 已开:
 *       CONFIG_DRIVERS_CIR_TX=y / CONFIG_DRIVERS_CIR_RX=y / CONFIG_DRIVERS_RC=y
 *
 * 数据格式: LIRC MODE2 —— 每个 32-bit 字用 LIRC_PULSE(us)/LIRC_SPACE(us)
 *           编码(bit24=电平, 低24位=微秒)。发送缓冲个数须为奇数(脉冲开头
 *           脉冲结尾),底层硬件缓冲上限 IR_TX_RAW_BUF_SIZE=256 项。
 ****************************************************************************/

#ifndef HOME_SCENSE_AC_IR_CONTROL_H
#define HOME_SCENSE_AC_IR_CONTROL_H

#include <stddef.h>
#include <stdint.h>
#include <stdbool.h>

/* LIRC 字符设备路径(drv_ir.c 里 R528_IR_NO=0 → /dev/lirc0)。 */
#ifndef AC_IR_DEVPATH
#define AC_IR_DEVPATH "/dev/lirc0"
#endif

/* 空调遥控主流为 38kHz 载波、约 1/3 占空比。个别品牌(部分东芝/夏普)用
 * 33~40kHz,如学习回放不通可在这里微调。 */
#define AC_IR_CARRIER_HZ 38000
#define AC_IR_DUTY_CYCLE 33

/* 学习抓帧的最大脉冲/间隔条数(足够容纳格力/美的等整机状态帧)。 */
#define AC_IR_MAX_WORDS 512

#ifdef __cplusplus
extern "C"
{
#endif

/****************************************************************************
 * 发射一帧原始 LIRC MODE2 波形。
 *   frame : LIRC_PULSE()/LIRC_SPACE() 编码的数组(脉冲开头)
 *   count : 数组元素个数;偶数时自动丢弃末尾(通常是收尾间隔)以满足奇数约束
 * 返回 0 成功, <0 为 -errno。
 ****************************************************************************/
int ac_ir_send_raw(const uint32_t *frame, size_t count);

/* 高层: 发送"开机/关机"帧(帧数据见 ac_ir_frames.h)。
 * 未录入真实帧时返回 -ENODATA 并打日志提示先学习。 */
int ac_ir_power_on(void);
int ac_ir_power_off(void);

/****************************************************************************
 * 从接收头抓取一帧红外波形到 buf(MODE2 字)。
 *   timeout_ms : 首个边沿到来的等待上限;帧内以 ~200ms 静默判定结束。
 * 返回捕获到的字数, <0 为 -errno。
 ****************************************************************************/
int ac_ir_capture(uint32_t *buf, size_t cap, int timeout_ms);

/* 抓一帧并把可直接粘贴进 ac_ir_frames.h 的 C 数组打到 stdout+syslog。
 * label 为数组名(如 "ac_frame_power_on")。返回字数或 <0。 */
int ac_ir_learn_dump(const char *label, int timeout_ms);

#ifdef __cplusplus
}
#endif

#endif /* HOME_SCENSE_AC_IR_CONTROL_H */

/****************************************************************************
 * app/home_scense/ac_ir_frames.h
 * 目标空调的红外时序帧(LIRC MODE2)。
 *
 * ★ 这些帧必须在真机上用板载接收头“学习”得到,不能凭空编造。★
 *
 * 采集步骤:
 *   1) 烧录带本改动的固件,进 nsh。
 *   2) 对豆包说「学习空调红外」→ 应用启动 10s 抓帧窗口(见 doubao_voice.c
 *      的 voice_intent_handle),此时把你家空调遥控器对准板子按「开/关」。
 *      (也可直接在代码里调用 ac_ir_learn_dump("ac_frame_power_on", 10000)。)
 *   3) 串口日志会打印形如下面的数组,整段复制回来替换占位内容。
 *   4) 把 AC_IR_HAVE_FRAMES 改为 1,重新编译。
 *
 * 说明: 帧以脉冲(PULSE)开头,元素个数为奇数;单帧建议 ≤255 项(硬件缓冲
 *       IR_TX_RAW_BUF_SIZE=256)。大金等超长帧可拆成多段分别发送。
 ****************************************************************************/

#ifndef HOME_SCENSE_AC_IR_FRAMES_H
#define HOME_SCENSE_AC_IR_FRAMES_H

#include <nuttx/lirc.h>   /* LIRC_PULSE / LIRC_SPACE */
#include <stdint.h>

/* 录入真实帧后改为 1 使能发送。为 0 时 ac_ir_power_on/off 只打日志提示。 */
#define AC_IR_HAVE_FRAMES 0

#if AC_IR_HAVE_FRAMES

/* ↓↓↓ 用 ac_ir_learn_dump 抓到的真实"开机"帧替换本占位数组 ↓↓↓ */
static const uint32_t g_ac_frame_power_on[] =
{
  /* 例(NEC 演示,非真实空调): 引导码 + 数据... */
  LIRC_PULSE(9000), LIRC_SPACE(4500),
  LIRC_PULSE(560),  LIRC_SPACE(560),
  LIRC_PULSE(560),  /* ...脉冲结尾, 奇数个 */
};

/* ↓↓↓ 真实"关机"帧 ↓↓↓ */
static const uint32_t g_ac_frame_power_off[] =
{
  LIRC_PULSE(9000), LIRC_SPACE(4500),
  LIRC_PULSE(560),  LIRC_SPACE(1690),
  LIRC_PULSE(560),
};

#endif /* AC_IR_HAVE_FRAMES */

#endif /* HOME_SCENSE_AC_IR_FRAMES_H */

/****************************************************************************
 * app/home_scense/ac_ir_control.c
 * 空调红外发射/学习 —— 走 /dev/lirc0 (NuttX LIRC)。
 ****************************************************************************/

#include "ac_ir_control.h"
#include "ac_ir_frames.h"

#include <nuttx/lirc.h>

#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <stdio.h>
#include <string.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <unistd.h>

#define AC_IR_LOG(fmt, ...) syslog(LOG_INFO, "[ac_ir] " fmt "\n", ##__VA_ARGS__)
#define AC_IR_ERR(fmt, ...) syslog(LOG_ERR,  "[ac_ir] " fmt "\n", ##__VA_ARGS__)

/****************************************************************************
 * 发射一帧原始波形
 ****************************************************************************/

int ac_ir_send_raw(const uint32_t *frame, size_t count)
{
  int fd;
  ssize_t nw;
  size_t bytes;

  if (frame == NULL || count == 0)
    {
      return -EINVAL;
    }

  /* LIRC 要求发送缓冲为奇数个(脉冲开头、脉冲结尾)。若抓帧时多录了收尾的
   * 静默间隔导致偶数,丢弃末尾一项即可。 */
  if ((count & 1) == 0)
    {
      count -= 1;
    }

  fd = open(AC_IR_DEVPATH, O_RDWR);
  if (fd < 0)
    {
      AC_IR_ERR("open %s failed: %d", AC_IR_DEVPATH, errno);
      return -errno;
    }

  /* ioctl 参数按值传递(见 drivers/rc/lirc_dev.c)。失败不致命:部分底层对
   * 载波/占空比用默认值,仍能发射。 */
  (void)ioctl(fd, LIRC_SET_SEND_MODE, LIRC_MODE_PULSE);
  (void)ioctl(fd, LIRC_SET_SEND_CARRIER, AC_IR_CARRIER_HZ);
  (void)ioctl(fd, LIRC_SET_SEND_DUTY_CYCLE, AC_IR_DUTY_CYCLE);

  bytes = count * sizeof(uint32_t);
  nw = write(fd, frame, bytes);
  close(fd);

  if (nw < 0)
    {
      AC_IR_ERR("write failed: %d", errno);
      return -errno;
    }

  AC_IR_LOG("sent %zu words (%zd bytes) @ %dHz", count, nw, AC_IR_CARRIER_HZ);
  return 0;
}

/****************************************************************************
 * 高层开/关
 ****************************************************************************/

int ac_ir_power_on(void)
{
#if AC_IR_HAVE_FRAMES
  return ac_ir_send_raw(g_ac_frame_power_on,
                        sizeof(g_ac_frame_power_on) / sizeof(uint32_t));
#else
  AC_IR_ERR("power_on: 尚未录入空调红外帧。请先『学习空调红外』并把抓到的"
            "数组填入 ac_ir_frames.h,再将 AC_IR_HAVE_FRAMES 置 1。");
  return -ENODATA;
#endif
}

int ac_ir_power_off(void)
{
#if AC_IR_HAVE_FRAMES
  return ac_ir_send_raw(g_ac_frame_power_off,
                        sizeof(g_ac_frame_power_off) / sizeof(uint32_t));
#else
  AC_IR_ERR("power_off: 尚未录入空调红外帧,见 ac_ir_frames.h 说明。");
  return -ENODATA;
#endif
}

/****************************************************************************
 * 学习: 从接收头抓一帧
 ****************************************************************************/

int ac_ir_capture(uint32_t *buf, size_t cap, int timeout_ms)
{
  struct pollfd pfd;
  int fd;
  size_t n = 0;

  if (buf == NULL || cap == 0)
    {
      return -EINVAL;
    }

  fd = open(AC_IR_DEVPATH, O_RDONLY | O_NONBLOCK);
  if (fd < 0)
    {
      AC_IR_ERR("open %s (rx) failed: %d", AC_IR_DEVPATH, errno);
      return -errno;
    }

  /* 尽力设为 MODE2 原始收码;不支持则忽略(默认即 raw)。 */
  (void)ioctl(fd, LIRC_SET_REC_MODE, LIRC_MODE_MODE2);

  pfd.fd = fd;
  pfd.events = POLLIN;

  while (n < cap)
    {
      /* 首个边沿等 timeout_ms;帧内相邻脉冲间隔很短,一旦静默 ~200ms
       * 视为整帧结束。 */
      int pr = poll(&pfd, 1, (n == 0) ? timeout_ms : 200);
      if (pr <= 0)
        {
          break;  /* 超时/出错 → 帧结束或未收到 */
        }

      if (pfd.revents & POLLIN)
        {
          uint32_t w;
          ssize_t r = read(fd, &w, sizeof(w));
          if (r == (ssize_t)sizeof(w))
            {
              buf[n++] = w;
              if (LIRC_IS_TIMEOUT(w))
                {
                  break;  /* 驱动显式给出超时标记 → 帧结束 */
                }
            }
          else if (r < 0 && errno != EAGAIN)
            {
              break;
            }
        }
    }

  close(fd);
  return (int)n;
}

int ac_ir_learn_dump(const char *label, int timeout_ms)
{
  static uint32_t buf[AC_IR_MAX_WORDS];
  const char *name = (label && label[0]) ? label : "ac_frame";
  int n;
  int i;

  AC_IR_LOG("学习开始: 请在 %d ms 内把空调遥控器对准板子按下目标键...",
            timeout_ms);

  n = ac_ir_capture(buf, AC_IR_MAX_WORDS, timeout_ms);
  if (n <= 0)
    {
      AC_IR_ERR("学习失败: 未捕获到红外信号 (ret=%d)。检查接收头/对准/距离。",
                n);
      return n < 0 ? n : -ETIMEDOUT;
    }

  /* 打印成可直接粘贴进 ac_ir_frames.h 的 C 数组。 */
  printf("\n/* ==== captured %d words, paste into ac_ir_frames.h ==== */\n",
         n);
  printf("static const uint32_t %s[] =\n{\n  ", name);
  for (i = 0; i < n; i++)
    {
      unsigned int us = LIRC_VALUE(buf[i]);
      const char *kind = LIRC_IS_PULSE(buf[i]) ? "LIRC_PULSE" :
                         LIRC_IS_TIMEOUT(buf[i]) ? "LIRC_TIMEOUT" : "LIRC_SPACE";
      printf("%s(%u),%s", kind, us,
             ((i + 1) % 4 == 0) ? "\n  " : " ");
    }
  printf("\n};\n/* ==== end (%d words) ==== */\n\n", n);

  AC_IR_LOG("学习完成: 捕获 %d 项。已打印数组 %s[]。", n, name);
  return n;
}

