/* IR_TX_TR 写入的是本次要发送的"总字节数", 硬件据此从 FIFO 连续取数发送。
 * FIFO 深度仅 128, 但整机空调帧(如美的)编码后常达 ~130 字节, 原代码只填一次、
 * 超 128 就 "fail to packet" 直接放弃(表现: ir_tx_test 短帧能发, "打开空调"
 * 长帧不发)。这里改为: 先填满 FIFO, 触发发送, 再随 FIFO 排空补写剩余字节,
 * 从而支持任意长度(≤ IR_TX_RAW_BUF_SIZE)的帧。≤128 的短帧行为与原来一致。 */
writel((cir_raw_buffer.tx_dcnt - 1), reg_addr + IR_TX_TR);

first = (cir_raw_buffer.tx_dcnt < IR_TX_FIFO_SIZE)
        ? cir_raw_buffer.tx_dcnt : IR_TX_FIFO_SIZE;
for (sent = 0; sent < first; sent++)
  writel(cir_raw_buffer.tx_buf[sent], reg_addr + IR_TX_FIFO_DR);

if (IR_TX_CYCLE_TYPE) {
  /* 触发发送。 */
  reg_val = readl(reg_addr + IR_TX_CR);
  reg_val |= (0x01 << 7);
  writel(reg_val, reg_addr + IR_TX_CR);

  /* 长帧: FIFO 有空位就补写剩余字节。guard 防止异常时死循环。 */
  guard = 0;
  while (sent < cir_raw_buffer.tx_dcnt && guard++ < 2000000) {
    avail = readl(reg_addr + IR_TX_TACR);   /* 空闲槽位数 */
    while (avail > 0 && sent < cir_raw_buffer.tx_dcnt) {
      writel(cir_raw_buffer.tx_buf[sent++], reg_addr + IR_TX_FIFO_DR);
      avail--;
    }
  }
} else {
  while (!cir_tx_fifo_empty()) {
    reg_val = readl(reg_addr + IR_TX_TACR);
  }
}

